getData=()=>{if(!this.self)return null;let p={};let err_element=null;let ff=null,field=null;let has_error=false;if(this.identity_prop)p[this.identity_prop]=this.identity_prop_value;this.self.find('.data-input').each(function(){let el=$(this);let f=el.data('field');if(el.data('error')==1){has_error=true;err_element=el;ff=el.data('ffield');field=f;return false;}
p[f]=el.val();});if(this.option.sub_prop)p[this.option.sub_prop]=this.option.sub_prop_function();if(has_error)return{'element':err_element,'field':field,'ff':ff,'data':null,'has_error':has_error};return{'data':p};}
getItemDetails(id,onFinish){let p={};p[this.identity_prop]=id;let that=this;window.vsapi.call(this.api_get,p).then((res)=>{if(res.status_code===200){let d=StringSanitizer.sanitizeObject(res.data,null,that.sanitize_excepts);onFinish(d);}else cv_interact.error(res.error_message);});}
