setData=(d=null,additional_props=null)=>{if(!d)d={};if(this.elError)this.elError.text(null);if(this.identity_prop)this.me[this.identity_prop]=d[this.identity_prop];document.getElementById(this.form_id).querySelectorAll('.data-input').forEach(el=>{let f=el.dataset.field;if(el.classList.contains('modal-select2')||el.classList.contains('select2')){VSUtil.setSelect2_value(el,d[f]);}else el.value=d[f]?d[f]:'';el.dataset.error=0;});if(additional_props){additional_props.map((prop)=>{this.me[prop.name]=prop.value;});}}
